import { EntityRepository, type IEntitiesRepository } from '@kinotic-ai/persistence'
import { Task } from '../../model/Task.js'


/**
 * Base Repository for interacting with Task entities
 * This class was generated by the Kinotic CLI. And will be overwritten if the CLI is run again.
 */
export class BaseTaskRepository extends EntityRepository<Task> {

  private readonly shouldValidate: boolean

  constructor(shouldValidate: boolean = true, entitiesRepository?: IEntitiesRepository) {
    super('minds-ignited', 'todo-neon', 'Task', entitiesRepository)
    this.shouldValidate = shouldValidate
  }

  protected override async beforeSaveOrUpdate(entity: Task): Promise<Task> {
    if (this.shouldValidate) {
      return this.validate(entity)
    } else {
      return entity
    }
  }

  protected override async beforeBulkSaveOrUpdate(entities: Task[]): Promise<Task[]> {
    if (this.shouldValidate) {
      const validatedEntities: Task[] = []
      for (let entity of entities) {
        validatedEntities.push(this.validate(entity))
      }
      return validatedEntities
    } else {
      return entities
    }
  }

  validate(entity: Task): Task {
    let ret: any
    if (entity) {
      ret = (ret ? ret : {})
      ret.id = entity.id
      ret.title = entity.title
      ret.notes = entity.notes
      ret.boardId = entity.boardId
      ret.status = entity.status
      ret.energy = entity.energy
      if (entity.tagIds) {
        ret.tagIds = []
        for (let entityTagIdsItem of entity.tagIds) {
          let retTagIdsValue: any
          retTagIdsValue = entityTagIdsItem
          ret.tagIds.push(retTagIdsValue)
        }
      }
      ret.position = entity.position
      ret.dueDate = entity.dueDate
      ret.completedAt = entity.completedAt
      ret.createdAt = entity.createdAt
      ret.updatedAt = entity.updatedAt
    }

    return ret
  }

}
